/**
 * Typed bindings. `Env` is generated by `wrangler types` into worker-configuration.d.ts;
 * this module narrows secrets and exposes fail-fast accessors.
 */
export type Bindings = Env;

export type AppEnv = { Bindings: Bindings; Variables: { requestId: string; cfCountry: string | null } };

const REQUIRED_IN_PROD = ["EIA_API_KEY", "BLS_API_KEY", "TURNSTILE_SECRET", "INDEXNOW_KEY"] as const;

export function requireSecret(env: Bindings, name: string): string {
  const v = (env as unknown as Record<string, unknown>)[name];
  if (typeof v !== "string" || v.length === 0) throw new Error(`Missing the ${name} secret`);
  return v;
}

export function assertProdSecrets(env: Bindings): void {
  if (env.ENVIRONMENT !== "production") return;
  for (const k of REQUIRED_IN_PROD) requireSecret(env, k);
}

export function isFixtureMode(env: Bindings): boolean {
  return env.FIXTURE_MODE === "1";
}
